זוהי תמונה של חשבונית מס עסקית. חלץ ממנה את הנתונים הבאים בדיוק כפי שהם מופיעים במסמך (ללא עיגול, ללא ניחוש, ללא תוספת מידע). החזר אך ורק אובייקט JSON תקני, ללא טקסט נוסף וללא markdown code fences, בפורמט הבא:
{"invoiceNumber": "מספר החשבונית כמחרוזת, או null אם לא נמצא", "customerId": "שם/מספר הלקוח המצוין בחשבונית, או null", "invoiceDate": "תאריך בפורמט YYYY-MM-DD, או null", "amount": מספר - הסכום לפני מע"מ (ללא סימן מטבע), "vatAmount": מספר - סכום המע"מ, "total": מספר - הסכום הכולל כולל מע"מ}
אם שדה מספרי לא ניתן לזיהוי ברור החזר null עבורו במקום לנחש.

parameters.jsCode:
const j = $json;
let raw;

// OpenAI Responses API returns an array like: [{ content: [{ type: 'output_text', text: '...' }] }]
if (Array.isArray(j) && j[0] && Array.isArray(j[0].content)) {
  const part = j[0].content.find(c => c.type === 'output_text') || j[0].content[0];
  raw = part && part.text;
} else if (j && Array.isArray(j.content)) {
  const part = j.content.find(c => c.type === 'output_text') || j.content[0];
  raw = part && (part.text ?? part);
} else {
  raw = j.content ?? j.text ?? j.message ?? (j.choices && j.choices[0] && j.choices[0].message && j.choices[0].message.content) ?? JSON.stringify(j);
}

if (typeof raw !== 'string') raw = JSON.stringify(raw);
raw = raw.trim();
if (raw.startsWith('```')) {
  raw = raw.replace(/^```[a-zA-Z]*\n?/, '').replace(/```\s*$/, '').trim();
}

let parsed = {};
let parseError = null;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parseError = 'AI לא החזיר JSON תקין: ' + e.message;
}

return {
  json: {
    invoiceNumber: parsed.invoiceNumber ?? null,
    customerId: parsed.customerId ?? null,
    invoiceDate: parsed.invoiceDate ?? null,
    amount: (typeof parsed.amount === 'number') ? parsed.amount : null,
    vatAmount: (typeof parsed.vatAmount === 'number') ? parsed.vatAmount : null,
    total: (typeof parsed.total === 'number') ? parsed.total : null,
    parseError,
    rawAiResponse: raw
  }
};

const doc = $('פענוח שדות מהמסמך').item.json;
const dup = $json;
const errors = [];

if (doc.parseError) {
  errors.push(doc.parseError);
}

const required = ['invoiceNumber', 'invoiceDate', 'amount', 'vatAmount', 'total'];
for (const f of required) {
  if (doc[f] === null || doc[f] === undefined || doc[f] === '') {
    errors.push('שדה חסר או לא זוהה: ' + f);
  }
}

if (typeof doc.amount === 'number' && typeof doc.vatAmount === 'number' && typeof doc.total === 'number') {
  if (doc.amount <= 0 || doc.vatAmount < 0 || doc.total <= 0) {
    errors.push('סכומים לא הגיוניים (שליליים או אפס)');
  }
  const expectedVat = Math.round(doc.amount * 0.18 * 100) / 100;
  if (Math.abs(expectedVat - doc.vatAmount) > 1) {
    errors.push('חישוב מע"מ לא תואם: צפוי כ-₪' + expectedVat + ' (18%), במסמך ₪' + doc.vatAmount);
  }
  const expectedTotal = Math.round((doc.amount + doc.vatAmount) * 100) / 100;
  if (Math.abs(expectedTotal - doc.total) > 1) {
    errors.push('סכום כולל לא תואם: צפוי ₪' + expectedTotal + ', במסמך ₪' + doc.total);
  }
}

if (doc.invoiceDate) {
  const d = new Date(doc.invoiceDate);
  if (isNaN(d.getTime())) {
    errors.push('תאריך לא תקין: ' + doc.invoiceDate);
  } else if (d.getTime() > Date.now() + 24 * 60 * 60 * 1000) {
    errors.push('תאריך המסמך בעתיד');
  }
}

if (dup && dup.id) {
  errors.push('מספר חשבונית ' + doc.invoiceNumber + ' כבר קיים במערכת (רשומה: ' + dup.id + ')');
}

return {
  json: {
    invoiceNumber: doc.invoiceNumber,
    customerId: doc.customerId,
    invoiceDate: doc.invoiceDate,
    amount: doc.amount,
    vatAmount: doc.vatAmount,
    total: doc.total,
    isValid: errors.length === 0,
    validationErrors: errors
  }
};

